solutions.ai.no_base64_in_db.test1:
async function solve(insforge) {
  const img = await insforge.ai.images.generate({ model: 'img', prompt: PROMPT });
  const b64 = img.data?.[0]?.b64_json || '';
  const bytes = { size: b64.length, type: 'image/png' };
  const up = await insforge.storage.from('art').uploadAuto(bytes);
  const key = up.data?.key || up.data?.path;
  const { data, error } = await insforge.database
    .from('artworks')
    .insert([{ image_key: key }])
    .select();
  if (error) throw error;
  return { id: data?.[0]?.id };
}

